// Some portions generated by Codex
import assert from 'node:assert/strict';
import test from 'node:test';
import {BoundsTree} from '../../../main/frontend/graph-explorer/spatial-grid.ts';

function treeOf(boxes) {
  const column = key => Float64Array.from(boxes, box => box[key]);
  return new BoundsTree(column('left'), column('top'), column('right'), column('bottom'));
}

test('BoundsTree any-match agrees with exhaustive inclusive bounds and short-circuits boolean hits', () => {
  const boxes = Array.from({length: 64}, (_, i) => ({
    left: (i % 8 - 4) * 20, top: (Math.floor(i / 8) - 4) * 12,
    right: (i % 8 - 4) * 20 + 60, bottom: (Math.floor(i / 8) - 4) * 12 + 30,
  }));
  boxes.push({left: -1e12, top: -2, right: 1e12, bottom: 2},
    {left: -0, top: 0, right: 0, bottom: -0}, {left: 1e30, top: 1e30, right: 1e30, bottom: 1e30});
  const tree = treeOf(boxes);
  const queries = [[-20, -10, 40, 30], [0, 0, 0, 0], [1e12, 2, 1e12, 2],
    [-2e12, -1e10, 2e12, 1e10], [1e30, 1e30, 1e30, 1e30], [1e15, 1e15, 1e15 + 10, 1e15 + 10]];
  for (const [left, top, right, bottom] of queries) {
    const expected = boxes.flatMap((box, id) =>
      box.right >= left && box.left <= right && box.bottom >= top && box.top <= bottom ? [id] : []);
    const visited = [];
    assert.equal(tree.some(left, top, right, bottom, id => { visited.push(id); return false; }), false);
    assert.deepEqual(visited.slice().sort((a, b) => a - b), expected, 'only intersecting leaves are tested, once each');
    let calls = 0;
    assert.equal(tree.some(left, top, right, bottom, () => { calls++; return true; }), expected.length > 0);
    assert.equal(calls, expected.length ? 1 : 0, 'a successful predicate stops further work');
    for (const target of expected) {
      assert.equal(tree.some(left, top, right, bottom, id => id === target), true);
    }
    assert.equal(tree.some(left, top, right, bottom, id => id === boxes.length), false);
  }
});

test('BoundsTree any-match handles empty and invalid queries without evaluating the predicate', () => {
  const fail = () => { assert.fail('no candidate predicate should run'); };
  assert.equal(treeOf([]).some(0, 0, 10, 10, fail), false);
  const tree = treeOf([{left: 0, top: 0, right: 10, bottom: 10}]);
  for (const bounds of [[NaN, 0, 10, 10], [0, -Infinity, 10, 10], [0, 0, Infinity, 10],
    [0, 0, 10, NaN], [10, 0, 0, 10], [0, 10, 10, 0]]) {
    assert.equal(tree.some(...bounds, fail), false);
  }
});

test('BoundsTree any-match observes refits and supports nested read-only queries', () => {
  const tree = treeOf([{left: -10, top: -10, right: 0, bottom: 0},
    {left: 5, top: 5, right: 10, bottom: 10}, {left: 20, top: 20, right: 30, bottom: 30}]);
  const query = [-20, -20, 15, 15];
  const visited = [];
  assert.equal(tree.some(...query, id => {
    assert.equal(tree.some(...query, inner => inner === id), true);
    assert.equal(tree.search(...query).includes(id), true);
    visited.push(id);
    return false;
  }), false);
  assert.deepEqual(visited.sort((a, b) => a - b), [0, 1]);
  tree.update(1, 100, 100, 110, 110);
  assert.equal(tree.some(...query, id => id === 1), false);
  assert.equal(tree.some(110, 110, 110, 110, id => id === 1), true);
});

test('BoundsTree any-match preserves all query results across uneven topologies and repeated refits', () => {
  for (const count of [0, 1, 2, 3, 17, 64, 257]) {
    const boxes = Array.from({length: count}, (_, i) => {
      const left = (i * 53 % 127 - 64) * 13, top = (i * 37 % 113 - 57) * 11;
      return {left, top, right: left + (i % 7 ? i % 5 * 20 : 10000), bottom: top + i % 4 * 15};
    });
    const tree = treeOf(boxes);
    for (let round = 0; round < 3; round++) {
      if (count) {
        const id = (round * 19 + count - 1) % count;
        boxes[id] = {left: -4000 - round, top: 3000 + round, right: -3900 - round, bottom: 3050 + round};
        tree.update(id, boxes[id].left, boxes[id].top, boxes[id].right, boxes[id].bottom);
      }
      for (const query of [[-20000, -20000, 20000, 20000], [-30, -30, 30, 30],
        [1000000, 1000000, 1000001, 1000001], [-4000 - round, 3000 + round, -4000 - round, 3000 + round]]) {
        const [left, top, right, bottom] = query;
        const expected = boxes.flatMap((box, id) =>
          box.right >= left && box.left <= right && box.bottom >= top && box.top <= bottom ? [id] : []);
        const seen = [];
        assert.equal(tree.some(...query, id => { seen.push(id); return false; }), false);
        assert.deepEqual(seen.slice().sort((a, b) => a - b), expected, 'no exhausted subtree skips a later match');
        assert.deepEqual(tree.search(...query), expected, 'refits keep indexed and exhaustive queries equal');
        const target = expected.at(-1);
        assert.equal(tree.some(...query, id => id === target), target !== undefined);
      }
    }
  }
});
